const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '植物细胞结构示意图' },
      { kind: 'text', payload: '细胞壁' },
      { kind: 'text', payload: '液泡' },
      { kind: 'text', payload: '细胞核' },
      { kind: 'text', payload: '示意图：仅表示结构位置关系，不代表真实比例与形态' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var paths = [];
    var children = [];

    function smoothClosed(pts) {
      var n = pts.length;
      var cmds = [['M', pts[0][0], pts[0][1]]];
      for (var i = 0; i < n; i++) {
        var p0 = pts[(i - 1 + n) % n];
        var p1 = pts[i];
        var p2 = pts[(i + 1) % n];
        var p3 = pts[(i + 2) % n];
        cmds.push(['C',
          p1[0] + (p2[0] - p0[0]) / 6,
          p1[1] + (p2[1] - p0[1]) / 6,
          p2[0] - (p3[0] - p1[0]) / 6,
          p2[1] - (p3[1] - p1[1]) / 6,
          p2[0], p2[1]]);
      }
      cmds.push(['Z']);
      return cmds;
    }

    function blob(cx, cy, rx, ry, wob, seed, n) {
      var pts = [];
      for (var i = 0; i < n; i++) {
        var a = (Math.PI * 2 * i) / n;
        var f = 1 + wob * Math.sin(i * 2.1 + seed) + wob * 0.55 * Math.cos(i * 3.7 + seed * 1.9);
        pts.push([cx + Math.cos(a) * rx * f, cy + Math.sin(a) * ry * f]);
      }
      return pts;
    }

    function addPath(id, cmds, fill, sw) {
      paths.push({ id: id, commands: cmds });
      var node = { type: 'path', pathId: id, fill: fill };
      if (sw) {
        node.stroke = { width: sw, cap: 'round', join: 'round' };
      }
      children.push(node);
    }

    function addLabel(idx, x, y, h, v, color) {
      children.push({
        type: 'label',
        contentId: metrics[idx].contentId,
        anchor: { x: x, y: y },
        hAlign: h,
        vAlign: v,
        color: color
      });
    }

    addPath('bg', [['M', 0, 0], ['L', W, 0], ['L', W, H], ['L', 0, H], ['Z']], '#F6F9F2', 0);

    var cx = W * 0.40;
    var cy = H * 0.55;
    var rx = W * 0.215;
    var ry = H * 0.29;
    var th = Math.min(rx, ry) * 0.075;

    addPath('wall', smoothClosed(blob(cx, cy, rx, ry, 0.015, 0.7, 12)), '#A7CB96', 3);
    addPath('cytoplasm', smoothClosed(blob(cx, cy, rx - th, ry - th, 0.015, 0.7, 12)), '#EFF7E8', 2);

    var vx = cx - rx * 0.20;
    var vy = cy - ry * 0.22;
    var vrx = rx * 0.60;
    var vry = ry * 0.44;
    addPath('vacuole', smoothClosed(blob(vx, vy, vrx, vry, 0.05, 2.3, 10)), '#CDE6F3', 2.5);

    var nx = cx + rx * 0.42;
    var ny = cy + ry * 0.52;
    var nr = Math.min(rx, ry) * 0.21;
    addPath('nucleus', visualSdk.circle(nx, ny, nr), '#C7A5D6', 2);
    addPath('nucleoplasm', visualSdk.circle(nx, ny, nr * 0.86), '#F1E4F6', 1.5);
    addPath('nucleolus', visualSdk.circle(nx - nr * 0.16, ny - nr * 0.12, nr * 0.30), '#9A6BB0', 1);

    var lx = W * 0.78;
    var lyWall = H * 0.17;
    var lyVac = H * 0.46;
    var lyNuc = H * 0.80;

    var wa = -Math.PI * 0.25;
    var wx = cx + Math.cos(wa) * rx * 0.985;
    var wy = cy + Math.sin(wa) * ry * 0.985;

    var va = -Math.PI * 0.20;
    var vtx = vx + Math.cos(va) * vrx * 0.95;
    var vty = vy + Math.sin(va) * vry * 0.95;

    var ddx = lx - nx;
    var ddy = lyNuc - ny;
    var ddl = Math.sqrt(ddx * ddx + ddy * ddy);
    var ntx = nx + (ddx / ddl) * nr * 0.98;
    var nty = ny + (ddy / ddl) * nr * 0.98;

    function leader(id, x1, y1, x2, y2) {
      addPath(id, [['M', x1, y1], ['L', x2, y2]], '#4A5A68', 1.6);
      addPath(id + 'Dot', visualSdk.circle(x2, y2, 3.5), '#4A5A68', 1);
    }

    leader('lWall', lx - 16, lyWall, wx, wy);
    leader('lVac', lx - 16, lyVac, vtx, vty);
    leader('lNuc', lx - 16, lyNuc, ntx, nty);

    addLabel(0, W * 0.05, H * 0.085, 'left', 'middle', '#2C3B45');
    addLabel(1, lx, lyWall, 'left', 'middle', '#2C3B45');
    addLabel(2, lx, lyVac, 'left', 'middle', '#2C3B45');
    addLabel(3, lx, lyNuc, 'left', 'middle', '#2C3B45');
    addLabel(4, W * 0.05, H * 0.95, 'left', 'middle', '#7A8A96');

    return {
      schemaVersion: 1,
      sceneId: 'plant-cell',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
